-c import sys
sys.path.insert(0, '.')
from app import create_app
from werkzeug.security import generate_password_hash
from datetime import date, timedelta
app = create_app()
with app.app_context():
    db = app.db
    seller = db.execute("SELECT user_id FROM Users WHERE email=:e", e='harvestseller@example.com')
    if not seller:
        seller_id = db.execute("INSERT INTO Users(email, password_hash, full_name, address, is_seller) VALUES(:e, :p, 'Harvest Seller', '1 Test St', TRUE) RETURNING user_id", e='harvestseller@example.com', p=generate_password_hash('SellerPass123!'))[0][0]
    else:
        seller_id = seller[0][0]
    buyer = db.execute("SELECT user_id FROM Users WHERE email=:e", e='harvestbuyer@example.com')
    if not buyer:
        buyer_id = db.execute("INSERT INTO Users(email, password_hash, full_name, address) VALUES(:e, :p, 'Harvest Buyer', '2 Test St') RETURNING user_id", e='harvestbuyer@example.com', p=generate_password_hash('BuyerPass123!'))[0][0]
    else:
        buyer_id = buyer[0][0]
    cat = db.execute("SELECT category_name FROM Categories WHERE category_name='Harvest'")
    if not cat:
        db.execute("INSERT INTO Categories(category_name) VALUES('Harvest')")
    prod = db.execute("SELECT product_id FROM Products WHERE name='Harvest Proof Product'")
    if not prod:
        product_id = db.execute("INSERT INTO Products(category_name, name, description, price, created_by) VALUES('Harvest', 'Harvest Proof Product', 'test', 100.00, :s) RETURNING product_id", s=seller_id)[0][0]
    else:
        product_id = prod[0][0]
    cart_item = db.execute("SELECT cart_item_id FROM CartItems WHERE user_id=:u AND product_id=:p", u=buyer_id, p=product_id)
    if not cart_item:
        db.execute("INSERT INTO CartItems(user_id, product_id, seller_id, quantity) VALUES(:u, :p, :s, 2)", u=buyer_id, p=product_id, s=seller_id)
    valid_coupon = db.execute("SELECT coupon_id FROM Coupons WHERE name='Harvest Valid Coupon'")
    if not valid_coupon:
        valid_id = db.execute("INSERT INTO Coupons(name, categories, discount, expiry_date) VALUES('Harvest Valid Coupon', 'all', 20, :d) RETURNING coupon_id", d=(date.today() + timedelta(days=30)))[0][0]
    else:
        valid_id = valid_coupon[0][0]
    expired_coupon = db.execute("SELECT coupon_id FROM Coupons WHERE name='Harvest Expired Coupon'")
    if not expired_coupon:
        expired_id = db.execute("INSERT INTO Coupons(name, categories, discount, expiry_date) VALUES('Harvest Expired Coupon', 'all', 50, :d) RETURNING coupon_id", d=(date.today() - timedelta(days=5)))[0][0]
    else:
        expired_id = expired_coupon[0][0]
    print('seeded seller_id=', seller_id, 'buyer_id=', buyer_id, 'product_id=', product_id, 'valid_coupon_id=', valid_id, 'expired_coupon_id=', expired_id)
